function shuffledDeck(){const a=QUESTIONS.map((_,i)=>i);for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function nextQuestion(r){r.answerDeadline=0;r.flightDuration=0;r.blockedPlayers=new Set();if(!r.deck.length)r.deck=shuffledDeck();const raw=QUESTIONS[r.deck.pop()];const pairs=raw[1].map((text,index)=>({text,index}));for(let i=pairs.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pairs[i],pairs[j]]=[pairs[j],pairs[i]]}r.question={text:raw[0],answers:pairs.map(x=>x.text),correct:pairs.findIndex(x=>x.index===raw[2])};r.answerer=null;r.flight=null;return r.question}
function publicState(r){const players={};for(const [id,p] of r.players)players[id]={id,name:p.name,points:p.points,platform:p.platform,stars:p.stars,slot:Number.isInteger(p.slot)?p.slot:0,online:p.online!==false};return {room:r.code,roomName:r.name||'Open room',players,hostId:r.hostId,started:!!r.started,question:r.question?{text:r.question.text,answers:r.question.answers}:null,answerer:r.answerer,blockedPlayers:[...(r.blockedPlayers||new Set())],answerDeadline:r.answerDeadline,flight:r.flight,flightDuration:r.flightDuration,started:r.started}}
function broadcast(r,type='state',extra={}){const payload=JSON.stringify({type,...extra,state:publicState(r)});for(const c of r.clients)if(c.readyState===1)c.send(payload)}
function roomCode(){let c;do{c=Math.random().toString(36).slice(2,8).toUpperCase()}while(rooms.has(c));return c}
function nextSlot(r){const used=new Set([...r.players.values()].map(p=>p.slot));for(let i=0;i<4;i++)if(!used.has(i))return i;return 0}
function startIfNeeded(r){/* Rooms wait for their host to press Start Game. */}
function sendDaily(ws,username){const a=accounts[username];if(a&&ws.readyState===1)ws.send(JSON.stringify({type:'daily',daily:questView(a),stars:a.stars||0}))}
function syncRoomDaily(r){for(const p of r.players.values()){const a=accounts[p.username];if(a){try{sendDailyToUser(p.username); }catch(e){console.error('[daily] sync failed:',e&&e.message||e)}}}}
function sendDailyToUser(username){const a=accounts[username];if(!a)return;for(const sock of activeSockets.values()){if(sock&&sock.username===username&&sock.readyState===1)sendDaily(sock,username)}}
function markFriendly(r){if(r.players.size<2)return;for(const p of r.players.values()){const a=accounts[p.username];if(a){const d=ensureDaily(a);d.friendly=true;completeQuest(a,'friendly')}}try{saveAccounts()}catch(e){console.error('[friendly] save failed:',e&&e.message||e)}syncRoomDaily(r)}
function addGame(username,r){const a=accounts[username];if(!a)return;const d=ensureDaily(a);if(!d.played){d.played=true;completeQuest(a,'dailyPlay')}a.games=(a.games||0)+1;saveAccounts()}
function recordCorrect(a){const d=ensureDaily(a);d.correctStreak++;d.correctToday++;if(d.correctStreak>=3)completeQuest(a,'correctStreak');if(d.correctToday>=5)completeQuest(a,'correctToday');saveAccounts()}
function finishGame(p){
 const a=accounts[p.username];if(!a)return;
 const d=ensureDaily(a);
 // Award the match win and daily quest exactly once per completed 10-point round.
 d.wins=(Number(d.wins)||0)+1;d.winStreak=(Number(d.winStreak)||0)+1;d.correctStreak=0;
 a.wins=(Number(a.wins)||0)+1;a.stars=(Number(a.stars)||0)+1;
 // The daily-win quest is tied to the match win, regardless of whether this player created or joined the room.
 completeQuest(a,'dailyWin');if(d.winStreak>=3)completeQuest(a,'winStreak');
 p.stars=Number(a.stars)||0;
 try{saveAccounts()}catch(err){console.error('[rank] failed to save winner rewards:',err&&err.stack||err)}
 sendDailyToUser(p.username);
}
function removeSocketFromRoom(sock, username){
 if(!sock)return;const room=rooms.get(sock.room);if(!room)return;
 const id=[...room.players.values()].find(p=>p.username===username)?.id;if(!id)return;
 room.clients.delete(sock);const leaving=room.players.get(id);if(leaving){clearTimeout(leaving.offlineTimer);room.players.delete(id);room.blockedPlayers?.delete(id);if(room.answerer===id){room.answerer=null;room.answerDeadline=0}if(room.flight===id){room.flight=null;room.flightDuration=0}if(room.hostId===id)room.hostId=room.players.keys().next().value||null;if(room.players.size===0)rooms.delete(room.code);else{if(room.answerer===null&&!room.flight)nextQuestion(room);broadcast(room,'event',{text:`${leaving.name} left the room.`})}}
 sock.room=null;
}
function loseGameStreak(username){const a=accounts[username];if(!a)return;ensureDaily(a).winStreak=0;saveAccounts()}
